module TopModule (
    input  logic       clk,
    input  logic       reset,
    output logic [4:0] q
);

    always_ff @(posedge clk) begin
        if (reset) begin
            q <= 5'd1;
        end else begin
            // Shift right Galois LFSR with taps at positions 5 and 3 
            // (corresponding to bit indices 4 and 2 in 0-indexed 5-bit vector)
            q <= {1'b0, q[4:1]} ^ (q[0] ? 5'b10100 : 5'b0);
        end
    end

endmodule

